import type { Kind, TypeLambda } from "../HKT.js";
import type { NoInfer } from "../Types.js";
type Map<F extends TypeLambda> = {
    <A, B>(f: (a: A) => B): <R, O, E>(self: Kind<F, R, O, E, A>) => Kind<F, R, O, E, B>;
    <R, O, E, A, B>(self: Kind<F, R, O, E, A>, f: (a: A) => B): Kind<F, R, O, E, B>;
};
type FlatMap<F extends TypeLambda> = {
    <A, R2, O2, E2, B>(f: (a: A) => Kind<F, R2, O2, E2, B>): <R1, O1, E1>(self: Kind<F, R1, O1, E1, A>) => Kind<F, R1 & R2, O1 | O2, E1 | E2, B>;
    <R1, O1, E1, A, R2, O2, E2, B>(self: Kind<F, R1, O1, E1, A>, f: (a: A) => Kind<F, R2, O2, E2, B>): Kind<F, R1 & R2, O1 | O2, E1 | E2, B>;
};
export declare const let_: <F extends TypeLambda>(map: Map<F>) => {
    <N extends string, A extends object, B>(name: Exclude<N, keyof A>, f: (a: NoInfer<A>) => B): <R, O, E>(self: Kind<F, R, O, E, A>) => Kind<F, R, O, E, { [K in keyof A | N]: K extends keyof A ? A[K] : B; }>;
    <R, O_1, E_1, A_1 extends object, N extends string, B_1>(self: Kind<F, R, O_1, E_1, A_1>, name: Exclude<N, keyof A_1>, f: (a: NoInfer<A_1>) => B_1): Kind<F, R, O_1, E_1, { [K in keyof A_1 | N]: K extends keyof A_1 ? A_1[K] : B_1; }>;
};
export declare const bindTo: <F extends TypeLambda>(map: Map<F>) => {
    <N extends string>(name: N): <R, O, E, A>(self: Kind<F, R, O, E, A>) => Kind<F, R, O, E, { [K in N]: A; }>;
    <R, O_1, E_1, A_1, N extends string>(self: Kind<F, R, O_1, E_1, A_1>, name: N): Kind<F, R, O_1, E_1, { [K in N]: A_1; }>;
};
export declare const bind: <F extends TypeLambda>(map: Map<F>, flatMap: FlatMap<F>) => {
    <N extends string, A extends object, R2, O2, E2, B>(name: Exclude<N, keyof A>, f: (a: NoInfer<A>) => Kind<F, R2, O2, E2, B>): <R1, O1, E1>(self: Kind<F, R1, O1, E1, A>) => Kind<F, R1 & R2, O1 | O2, E1 | E2, { [K in keyof A | N]: K extends keyof A ? A[K] : B; }>;
    <R1, O1_1, E1_1, A_1 extends object, N extends string, R2_1, O2_1, E2_1, B_1>(self: Kind<F, R1, O1_1, E1_1, A_1>, name: Exclude<N, keyof A_1>, f: (a: NoInfer<A_1>) => Kind<F, R2_1, O2_1, E2_1, B_1>): Kind<F, R1 & R2_1, O1_1 | O2_1, E1_1 | E2_1, { [K in keyof A_1 | N]: K extends keyof A_1 ? A_1[K] : B_1; }>;
};
export {};
